           <p class="error-message" id="phoneError" aria-live="polite"></p>
         </div>

         <div class="actions">
           <button type="submit">Submit request</button>
           <p class="status-message" id="formStatus" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("formStatus");

     const fields = {
       fullName: {
         input: document.getElementById("fullName"),
         error: document.getElementById("fullNameError"),
         validate(value) {
           if (!value.trim()) {
             return "Full name is required.";
           }

           if (value.trim().length < 2) {
             return "Enter your full name.";
           }

           return "";
         }
       },
       email: {
         input: document.getElementById("email"),
         error: document.getElementById("emailError"),
         validate(value) {
           if (!value.trim()) {
             return "Email address is required.";
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return "Enter a valid email address.";
           }

           return "";
         }
       },
       phone: {
         input: document.getElementById("phone"),
         error: document.getElementById("phoneError"),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return "";
           }

           const phonePattern = /^\+?[0-9\s\-().]{7,20}$/;
           if (!phonePattern.test(trimmedValue)) {
             return "Use a valid phone number format, such as +1 555-123-4567.";
           }

           return "";
         }
       }
     };

     function setFieldError(fieldName, message) {
       const { input, error } = fields[fieldName];
       const fieldWrapper = input.closest(".form-field");

       error.textContent = message;
       input.setAttribute("aria-invalid", message ? "true" : "false");
       fieldWrapper.classList.toggle("has-error", Boolean(message));
     }

     function validateField(fieldName) {
       const field = fields[fieldName];
       const message = field.validate(field.input.value);
       setFieldError(fieldName, message);
       return !message;
     }

     Object.keys(fields).forEach((fieldName) => {
       const { input } = fields[fieldName];
       input.addEventListener("blur", () => {
         validateField(fieldName);
       });

       input.addEventListener("input", () => {
         if (input.getAttribute("aria-invalid") === "true") {
           validateField(fieldName);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       statusMessage.textContent = "";

       const isFormValid = Object.keys(fields)
         .map(validateField)
         .every(Boolean);

       if (!isFormValid) {
         const firstInvalidField = Object.values(fields).find(({ input }) => input.getAttribute("aria-invalid") === "true");
         if (firstInvalidField) {
           firstInvalidField.input.focus();
         }
         return;
       }

       statusMessage.textContent = "Your support request is ready to send.";
       form.reset();
       Object.keys(fields).forEach((fieldName) => {
         setFieldError(fieldName, "");
       });
